import type { ProcessRunResult } from 'claude-code'

export const POLL_INTERVAL_MS = 15_000
export const AGENTS_ARGV: readonly string[] = ['claude', 'agents', '--json', '--all']
export const AGENTS_CACHE_KEY = 'agents'

const ENDED_STATES = new Set(['done', 'failed', 'stopped'])
const NOT_ON_PATH = /ENOENT|not found|no such file|cannot find/i

export type SessionKind = 'interactive' | 'background'

export type SessionRow = {
  key: string
  sessionId: string | null
  name: string
  kind: SessionKind
  word: string
  waitingFor: string | null
  cwd: string
  startedAt: number
  stateSince: number
  isEnded: boolean
}

export type AgentsFailure =
  | { kind: 'exit'; exitCode: number }
  | { kind: 'not-on-path' }
  | { kind: 'not-a-list' }
  | { kind: 'did-not-run' }
  | { kind: 'cut' }

export type AgentsOutcome = { kind: 'ok'; rows: SessionRow[]; skipped: number } | AgentsFailure

export type Listed = { at: number; rows: SessionRow[] }

export type GitPlace = { worktree: string; branch: string | null }

export type PlaceEntry = { cwd: string; place: GitPlace }

export type AgentsCache = {
  at: number
  failure: AgentsFailure | null
  listed: Listed | null
  places: Record<string, PlaceEntry>
}

export type AgentsHost = {
  now: () => Promise<number>
  run: (argv: readonly string[]) => Promise<ProcessRunResult>
  load: () => Promise<unknown>
  save: (cache: AgentsCache) => Promise<void>
  log: (line: string) => void
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value)
}

function optionalText(value: unknown): string | null {
  return typeof value === 'string' && value !== '' ? value : null
}

function rowKey(entry: Record<string, unknown>, sessionId: string | null): string {
  if (sessionId !== null) return sessionId
  if (typeof entry.id === 'string') return `bg:${entry.id}`
  return `pid:${String(entry.pid)}`
}

function rowName(entry: Record<string, unknown>, sessionId: string | null): string {
  return (
    optionalText(entry.name) ??
    optionalText(entry.id) ??
    sessionId?.slice(0, 8) ??
    `pid ${String(entry.pid)}`
  )
}

function readRow(entry: unknown): SessionRow | null {
  if (!isRecord(entry)) return null
  const { kind, cwd, startedAt } = entry
  if (kind !== 'interactive' && kind !== 'background') return null
  if (typeof cwd !== 'string' || typeof startedAt !== 'number') return null
  const sessionId = optionalText(entry.sessionId)
  const word = optionalText(kind === 'background' ? entry.state : entry.status) ?? 'unknown'
  return {
    key: rowKey(entry, sessionId),
    sessionId,
    name: rowName(entry, sessionId),
    kind,
    word,
    waitingFor: optionalText(entry.waitingFor),
    cwd,
    startedAt,
    stateSince: startedAt,
    isEnded: kind === 'background' && ENDED_STATES.has(word),
  }
}

export function parseAgents(stdout: string): AgentsOutcome {
  let parsed: unknown
  try {
    parsed = JSON.parse(stdout)
  } catch {
    return { kind: 'not-a-list' }
  }
  if (!Array.isArray(parsed)) return { kind: 'not-a-list' }
  const rows = parsed.map(readRow).filter((row) => row !== null)
  return { kind: 'ok', rows, skipped: parsed.length - rows.length }
}

function isTextOrNull(value: unknown): boolean {
  return value === null || typeof value === 'string'
}

function isSessionRow(value: unknown): value is SessionRow {
  return (
    isRecord(value) &&
    typeof value.key === 'string' &&
    isTextOrNull(value.sessionId) &&
    typeof value.name === 'string' &&
    (value.kind === 'interactive' || value.kind === 'background') &&
    typeof value.word === 'string' &&
    isTextOrNull(value.waitingFor) &&
    typeof value.cwd === 'string' &&
    typeof value.startedAt === 'number' &&
    typeof value.stateSince === 'number' &&
    typeof value.isEnded === 'boolean'
  )
}

const FAILURE_KINDS = new Set(['not-on-path', 'not-a-list', 'did-not-run', 'cut'])

function isFailure(value: unknown): value is AgentsFailure | null {
  if (value === null) return true
  if (!isRecord(value) || typeof value.kind !== 'string') return false
  if (value.kind === 'exit') return typeof value.exitCode === 'number'
  return FAILURE_KINDS.has(value.kind)
}

function isListed(value: unknown): value is Listed | null {
  if (value === null) return true
  return (
    isRecord(value) &&
    typeof value.at === 'number' &&
    Array.isArray(value.rows) &&
    value.rows.every(isSessionRow)
  )
}

function isPlaceEntry(value: unknown): value is PlaceEntry {
  return (
    isRecord(value) &&
    typeof value.cwd === 'string' &&
    isRecord(value.place) &&
    typeof value.place.worktree === 'string' &&
    isTextOrNull(value.place.branch)
  )
}

export function readCache(value: unknown): AgentsCache | undefined {
  if (!isRecord(value)) return undefined
  const { at, failure, listed, places } = value
  if (typeof at !== 'number' || !isFailure(failure) || !isListed(listed)) return undefined
  if (!isRecord(places) || !Object.values(places).every(isPlaceEntry)) return undefined
  return value as AgentsCache
}

function skippedLine(skipped: number): string {
  const rows = skipped === 1 ? 'row' : 'rows'
  return `handily-board: skipped ${String(skipped)} unreadable ${rows} of claude agents --json`
}

async function runAgents(host: AgentsHost): Promise<AgentsOutcome> {
  let result: ProcessRunResult
  try {
    result = await host.run(AGENTS_ARGV)
  } catch (error) {
    const reason = error instanceof Error ? error.message : String(error)
    host.log(`handily-board: claude agents --json could not run: ${reason}`)
    return NOT_ON_PATH.test(reason) ? { kind: 'not-on-path' } : { kind: 'did-not-run' }
  }
  if (result.exitCode !== 0) return { kind: 'exit', exitCode: result.exitCode }
  if (result.isStdoutTruncated) return { kind: 'cut' }
  const outcome = parseAgents(result.stdout)
  if (outcome.kind === 'ok' && outcome.skipped > 0) host.log(skippedLine(outcome.skipped))
  return outcome
}

function segments(path: string): string[] {
  return path.split(/[\\/]+/).filter((part) => part !== '')
}

function lastSegments(path: string, count: number): string {
  const parts = segments(path)
  return parts.length === 0 ? path : parts.slice(-count).join('/')
}

export function lastSegment(path: string): string {
  return lastSegments(path, 1)
}

export async function gitPlace(host: AgentsHost, cwd: string): Promise<GitPlace> {
  const fallback = { worktree: lastSegment(cwd), branch: null }
  let paths: ProcessRunResult
  try {
    paths = await host.run([
      'git',
      '-C',
      cwd,
      'rev-parse',
      '--path-format=absolute',
      '--show-toplevel',
      '--git-dir',
      '--git-common-dir',
    ])
  } catch {
    return fallback
  }
  const [top, gitDir, commonDir] = paths.stdout.trim().split(/\r?\n/)
  if (paths.exitCode !== 0 || top === undefined || top === '') return fallback
  const isLinked = gitDir !== undefined && commonDir !== undefined && gitDir !== commonDir
  const worktree = lastSegments(top, isLinked ? 2 : 1)
  let branch: ProcessRunResult
  try {
    branch = await host.run(['git', '-C', cwd, 'branch', '--show-current'])
  } catch {
    return { worktree, branch: null }
  }
  const name = branch.stdout.trim()
  return { worktree, branch: branch.exitCode === 0 && name !== '' ? name : null }
}

async function placesFor(
  host: AgentsHost,
  rows: readonly SessionRow[],
  previous: Record<string, PlaceEntry>,
): Promise<Record<string, PlaceEntry>> {
  const places: Record<string, PlaceEntry> = {}
  for (const row of rows) {
    const known = previous[row.key]
    places[row.key] =
      known?.cwd === row.cwd ? known : { cwd: row.cwd, place: await gitPlace(host, row.cwd) }
  }
  return places
}

function isSameState(row: SessionRow, seen: SessionRow): boolean {
  return seen.word === row.word && seen.waitingFor === row.waitingFor
}

function withStateSince(
  rows: readonly SessionRow[],
  previous: Listed | null,
  now: number,
): SessionRow[] {
  const seen = new Map((previous?.rows ?? []).map((row) => [row.key, row]))
  return rows.map((row) => {
    const before = seen.get(row.key)
    if (!before) return row
    return { ...row, stateSince: isSameState(row, before) ? before.stateSince : now }
  })
}

export function isFresh(cache: AgentsCache | undefined, now: number): boolean {
  if (!cache) return false
  const age = now - cache.at
  return age >= 0 && age < POLL_INTERVAL_MS
}

export async function pollAgents(host: AgentsHost): Promise<AgentsCache> {
  const now = await host.now()
  const previous = readCache(await host.load())
  if (previous && isFresh(previous, now)) return previous
  const answered = await runAgents(host)
  const known = previous?.places ?? {}
  let cache: AgentsCache
  if (answered.kind === 'ok') {
    const rows = withStateSince(answered.rows, previous?.listed ?? null, now)
    const places = await placesFor(host, rows, known)
    cache = { at: now, failure: null, listed: { at: now, rows }, places }
  } else {
    cache = { at: now, failure: answered, listed: previous?.listed ?? null, places: known }
  }
  await host.save(cache)
  return cache
}

